-- MySQL 8+ deployment schema. SQLAlchemy creates the SQLite demo schema automatically.
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,name VARCHAR(120) NOT NULL,age INT NOT NULL,gender VARCHAR(30),grade VARCHAR(40) NOT NULL,school VARCHAR(140),language VARCHAR(20),guardian_name VARCHAR(120),guardian_contact VARCHAR(120),created_at DATETIME NOT NULL,INDEX(owner_id),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE assessments (id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,status VARCHAR(30),questionnaire JSON,reading_text TEXT,writing_text TEXT,dyslexia_score FLOAT NOT NULL,dysgraphia_score FLOAT NOT NULL,overall_risk FLOAT NOT NULL,confidence FLOAT NOT NULL,risk_level VARCHAR(20),indicators JSON,nlp_result JSON,created_at DATETIME NOT NULL,INDEX(student_id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE handwriting_samples (id INT AUTO_INCREMENT PRIMARY KEY,assessment_id INT NOT NULL,filename VARCHAR(255) NOT NULL,ocr_text TEXT,created_at DATETIME NOT NULL,INDEX(assessment_id),FOREIGN KEY(assessment_id) REFERENCES assessments(id));
